//! Auto-generated compile-time static databases for PlatinumGames material layouts,
//! WMB1/WMB2/WMB3 vertex formats, and cross-game bone mappings.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum VertexFieldType {
    Position,      // 12 bytes (f32 x 3)
    Mapping,       // 4 bytes (f16 x 2)
    Normal,        // 4 bytes (packed 10-10-10 or i8x4)
    Tangents,      // 4 bytes (u8x4 normalized)
    BoneInfos,     // 8 bytes (u8x4 indices + u8x4 weights)
    Color,         // 4 bytes (u8x4 RGBA)
    FloatNormal,   // 12 bytes (f32 x 3)
    HalfNormal,    // 8 bytes (f16 x 4)
    FloatMapping,  // 8 bytes (f32 x 2)
}

impl VertexFieldType {
    pub const fn byte_size(self) -> usize {
        match self {
            Self::Position => 12,
            Self::Mapping => 4,
            Self::Normal => 4,
            Self::Tangents => 4,
            Self::BoneInfos => 8,
            Self::Color => 4,
            Self::FloatNormal => 12,
            Self::HalfNormal => 8,
            Self::FloatMapping => 8,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct VertexFieldSpec {
    pub name: &'static str,
    pub field_type: VertexFieldType,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WmbVertexLayout {
    pub vertex_flags: u32,
    pub ex_data_size: i8,
    pub ex_data: i8,
    pub primary_fields: &'static [VertexFieldSpec],
    pub ex_fields: &'static [VertexFieldSpec],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Wmb3VertexLayout {
    pub vertex_flags: u32,
    pub primary_fields: &'static [VertexFieldSpec],
    pub ex_fields: &'static [VertexFieldSpec],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum MaterialParamType {
    Sampler2D,
    SamplerCube,
    F4Float,
    F4Float2,
    F4Float3,
    F4Float4,
    F4Ignored,
}

impl MaterialParamType {
    pub const fn is_sampler(self) -> bool {
        matches!(self, Self::Sampler2D | Self::SamplerCube)
    }
    pub const fn dword_count(self) -> usize {
        match self {
            Self::Sampler2D | Self::SamplerCube => 1,
            _ => 4,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct MaterialFieldSpec {
    pub name: &'static str,
    pub param_type: MaterialParamType,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub struct MaterialTypeSpec {
    pub mat_type: i16,
    pub byte_size: usize,
    pub shader: Option<&'static str>,
    pub layout: &'static [MaterialFieldSpec],
}

