pub fn lookup_wmb_vertex_layout(vertex_flags: u32, ex_data_size: i8, ex_data: i8) -> Option<&'static WmbVertexLayout> {
    WMB_VERTEX_LAYOUTS.iter().find(|l| {
        l.vertex_flags == vertex_flags && l.ex_data_size == ex_data_size && l.ex_data == ex_data
    })
}

impl Wmb3VertexLayout {
    pub fn primary_stride(&self) -> usize {
        self.primary_fields.iter().map(|f| f.field_type.byte_size()).sum()
    }
    pub fn ex_stride(&self) -> usize {
        self.ex_fields.iter().map(|f| f.field_type.byte_size()).sum()
    }
}

pub fn lookup_wmb3_vertex_layout(vertex_flags: u32) -> Option<&'static Wmb3VertexLayout> {
    WMB3_VERTEX_LAYOUTS.iter().find(|l| l.vertex_flags == vertex_flags)
}

pub fn lookup_wmb3_vertex_layout_with_strides(
    vertex_flags: u32,
    primary_stride: u32,
    ex_stride: u32,
) -> Option<&'static Wmb3VertexLayout> {
    if let Some(exact) = WMB3_VERTEX_LAYOUTS.iter().find(|l| {
        l.vertex_flags == vertex_flags
            && l.primary_stride() == primary_stride as usize
            && l.ex_stride() == ex_stride as usize
    }) {
        return Some(exact);
    }
    if let Some(by_flags) = WMB3_VERTEX_LAYOUTS.iter().find(|l| l.vertex_flags == vertex_flags) {
        return Some(by_flags);
    }
    WMB3_VERTEX_LAYOUTS.iter().find(|l| {
        l.primary_stride() == primary_stride as usize && l.ex_stride() == ex_stride as usize
    })
}

pub fn lookup_material_type(mat_type: i16) -> Option<&'static MaterialTypeSpec> {
    MATERIAL_DATABASE.binary_search_by_key(&mat_type, |m| m.mat_type).ok().map(|i| &MATERIAL_DATABASE[i])
}

pub fn max_material_byte_size() -> usize {
    MATERIAL_DATABASE.iter().map(|m| m.byte_size).max().unwrap_or(372)
}
